const NOW = Date.now();
const cfg = (($('Config ophalen').all()[0]||{}).json)||{};
const DEFAULT_TH = (cfg.thresholds && cfg.thresholds.default) || {};
const MACHINES = $('Machines ophalen').all().map(x=>x.json);
const TH = DEFAULT_TH;
const OFFLINE_MIN = TH.offline_min ?? 10, UPD_MANY = TH.updates_many ?? 20;
const BAT_MIN = TH.bat_min ?? 15, DISK_WARN = TH.disk_warn ?? 80, DISK_ALARM = TH.disk_alarm ?? 90;
const TEMP_ALARM = TH.temp_alarm ?? 90, DISK_FORECAST_DAYS = TH.disk_forecast_days ?? 14;
const RAM_ALARM = TH.ram_alarm ?? 85, SWAP_ALARM = TH.swap_alarm ?? 50;
const num = v => (v==null||v==='')?NaN:Number(v);
const tms = r => Date.parse(r.ts);
const hhmm = () => new Date(NOW).toLocaleTimeString('nl-NL',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Amsterdam'});
const asArr = v => Array.isArray(v)?v:(typeof v==='string'?(()=>{try{return JSON.parse(v)}catch(e){return null}})():null);
const latest = $input.all().map(i=>i.json);
const rows=MACHINES.map(m=>({...latest.find(r=>r.machine===m.machine),machine:m.machine,thresholds:m.thresholds}));          // v_latest: 1 rij per machine
const online = rows.filter(r=>!isNaN(tms(r)) && (NOW-tms(r))/60000 <= ({...DEFAULT_TH,...(r.thresholds||{})}.offline_min??10));
const label = m => (m||'?');
const culprit = procs => { const arr=asArr(procs)||[]; if(!arr||!arr.length) return null; const top=arr.slice().sort((a,b)=>(b.cpu||0)-(a.cpu||0))[0]; return (top && top.name) || null; };
const culpritMem = procs => { const arr=asArr(procs)||[]; if(!arr||!arr.length) return null; const top=arr.slice().sort((a,b)=>(b.mem||0)-(a.mem||0))[0]; return (top && top.name) ? (top.name+' ('+top.mem+'% RAM)') : null; };

const t=hhmm(); const store=$getWorkflowStaticData('global'); store.a=store.a||{};
const out=[]; const t2=(m,k)=>m+':'+k;
function fire(m,key,active,spec,caption){
  const id=t2(m,key); const was=!!store.a[id];
  if(active && !was){ store.a[id]=true; out.push({json:{caption,spec}}); }
  else if(!active && was){ store.a[id]=false;
    out.push({json:{caption:'✓ Opgelost — '+m+' · '+t,
      spec:{title:'✓ Opgelost — '+m,subtitle:t,state:'ok',
        rows:[{label:key.toUpperCase(),value:'weer OK',status:'ok'}],footer:'SysDash · hersteld · '+t}}}); }
}
// per machine de vitale checks
for(const d of rows){
  const T={...DEFAULT_TH,...(d.thresholds||{})};
  const OFFLINE_MIN=T.offline_min??10,UPD_MANY=T.updates_many??20,BAT_MIN=T.bat_min??15,DISK_WARN=T.disk_warn??80,DISK_ALARM=T.disk_alarm??90,TEMP_ALARM=T.temp_alarm??90,DISK_FORECAST_DAYS=T.disk_forecast_days??14,RAM_ALARM=T.ram_alarm??85,SWAP_ALARM=T.swap_alarm??50;
  const m=label(d.machine); const off=isNaN(tms(d))||(NOW-tms(d))/60000>OFFLINE_MIN;
  fire(m,'offline',off,{title:'▲ OFFLINE — '+m,subtitle:'sinds '+t,state:'alert',
    rows:[{label:'MACHINE',value:'geen data > '+OFFLINE_MIN+' min',status:'high'}],footer:'SysDash · offline · '+t},
    '▲ OFFLINE — '+m+' · '+t);
  if(off) continue; // rest alleen als 'ie online is
  const disk=num(d.disk), temp=num(d.temp), up=d.net_up, mem=num(d.mem), swap=num(d.swap);
  const ex = d.extra || {};

  store.hotSince=store.hotSince||{};
  if(!isNaN(temp)&&temp>=TEMP_ALARM){store.hotSince[m]=store.hotSince[m]||NOW;} else delete store.hotSince[m];
  for(const diskRow of (d.disks?.length?d.disks:[{mount:"systeem",pct:disk}])){const pct=num(diskRow.pct);fire(m,'mount:'+diskRow.mount,!isNaN(pct)&&pct>=DISK_ALARM,{title:'Schijf bijna vol — '+m,subtitle:t,state:'alert',rows:[{label:String(diskRow.mount),value:pct+'%',pct,status:'high'}],footer:'SysDash'},'Schijf bijna vol — '+m+' '+diskRow.mount);}
  const tempCul = culprit(d.top_procs);
  const tempRows = [{label:'TEMP',value:Math.round(temp)+'°C',status:'high'}];
  if(tempCul) tempRows.push({label:'VEROORZAKER',value:tempCul,status:'warn'});
  fire(m,'temp',!isNaN(temp)&&temp>=TEMP_ALARM&&NOW-(store.hotSince[m]||NOW)>=120000,{title:'▲ TE HEET — '+m,subtitle:t,state:'alert',
    rows:tempRows,footer:'SysDash · temp · '+t},
    '▲ TE HEET — '+m+' · '+Math.round(temp)+'°C'+(tempCul?(' · '+tempCul):''));

  fire(m,'net',up===false,{title:'▲ GEEN INTERNET — '+m,subtitle:t,state:'alert',
    rows:[{label:'NETWERK',value:'geen verbinding',status:'high'}],footer:'SysDash · netwerk · '+t},
    '▲ GEEN INTERNET — '+m+' · '+t);

  // trend: schijf loopt vol — lineaire prognose, door de agent zelf berekend uit zijn eigen historie
  const daysLeft = num(ex.disk_days_left);
  fire(m,'schijftrend',!isNaN(daysLeft)&&daysLeft<=DISK_FORECAST_DAYS,{title:'● Schijf loopt vol — '+m,subtitle:t,state:'ok',
    rows:[{label:'PROGNOSE',value:'over ~'+Math.round(daysLeft)+' dagen vol',status:'warn'}],footer:'SysDash · trend · '+t},
    '● Schijf loopt vol — '+m+' · nog ~'+Math.round(daysLeft)+' dagen');

  // trend: RAM én swap allebei onder druk (thrashing) — bewust geen losse RAM-piek, dat is ruis
  const memCul = culpritMem(ex.top_procs_mem);
  const thrashRows = [{label:'RAM',value:Math.round(mem)+'%',status:'high'},{label:'SWAP',value:Math.round(swap)+'%',status:'high'}];
  if(memCul) thrashRows.push({label:'VEROORZAKER',value:memCul,status:'warn'});
  fire(m,'geheugen',!isNaN(mem)&&!isNaN(swap)&&mem>=RAM_ALARM&&swap>=SWAP_ALARM,{title:'▲ RAM+SWAP VOL — '+m,subtitle:t,state:'alert',
    rows:thrashRows,footer:'SysDash · geheugen · '+t},
    '▲ RAM+SWAP VOL — '+m+(memCul?(' · '+memCul):''));
}
return out;
